steps.body:
Count the paths from the top-left corner of a grid to the bottom-right, moving only right or down, around walls. Every path into a cell arrives from above or from the left, so a cell's count is the sum of those two. Fill a 2D table row by row, so both are ready when you need them:

```cpp
std::vector<std::string> grid = {"...", ".#.", "..."};   // # is a wall
int rows = static_cast<int>(grid.size());
int cols = static_cast<int>(grid[0].size());
std::vector<std::vector<long long>> dp(rows, std::vector<long long>(cols, 0));
for (int r = 0; r < rows; ++r) {
    for (int c = 0; c < cols; ++c) {
        if (grid[r][c] == '#') {
            continue;                   // no path goes through a wall
        }
        if (r == 0 && c == 0) {
            dp[r][c] = 1;               // the start
            continue;
        }
        if (r > 0) {
            dp[r][c] += dp[r - 1][c];   // from above
        }
        if (c > 0) {
            dp[r][c] += dp[r][c - 1];   // from the left
        }
    }
}
std::cout << dp[rows - 1][cols - 1] << '\n';   // 2
```

A wall keeps its 0, so it adds nothing to the cells after it. The `r > 0` and `c > 0` checks cover the top row and the left column, which have only one way in. The same table finds the cheapest path when each cell holds a cost: add the cell's own cost to the smaller of above and left instead of the sum. Either way it costs O(rows * cols).

example.code:
#include <iostream>
#include <string>
#include <vector>

int main() {
    int rows = 0;
    int cols = 0;
    std::cin >> rows >> cols;
    std::vector<std::string> grid(rows);
    for (int r = 0; r < rows; ++r) {
        std::cin >> grid[r];
    }

    std::vector<std::vector<long long>> dp(rows, std::vector<long long>(cols, 0));
    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            if (grid[r][c] == '#') {
                continue;
            }
            if (r == 0 && c == 0) {
                dp[r][c] = 1;
                continue;
            }
            if (r > 0) {
                dp[r][c] += dp[r - 1][c];
            }
            if (c > 0) {
                dp[r][c] += dp[r][c - 1];
            }
        }
    }
    std::cout << "paths " << dp[rows - 1][cols - 1] << '\n';
    return 0;
}

