#include <vector>

int main() {
    int rows = 0;
    int cols = 0;
    std::cin >> rows >> cols;
    std::vector<std::vector<int>> cost(rows, std::vector<int>(cols, 0));
    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            std::cin >> cost[r][c];
        }
    }
    std::vector<std::vector<long long>> dp(rows, std::vector<long long>(cols, 0));
    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            if (r == 0 && c == 0) {
                dp[r][c] = cost[r][c];
            } else if (r == 0) {
                dp[r][c] = cost[r][c] + dp[r][c - 1];
            } else if (c == 0) {
                dp[r][c] = cost[r][c] + dp[r - 1][c];
            } else {
                dp[r][c] = cost[r][c] + std::min(dp[r - 1][c], dp[r][c - 1]);
            }
        }
    }
    std::cout << "cost " << dp[rows - 1][cols - 1] << '\n';
    return 0;
}
